import type {Handler} from './router.ts';
export function withErrors(handler: Handler): Handler {
  return async (req,res,next) => { try { return await handler(req,res,next); } catch(error) { next(error); } };
}
export interface Request { fail?: boolean; id: string; }
export interface Response { send(value: string): string; }
export type Next = (error: unknown) => void;
export type Handler = (req: Request, res: Response, next: Next) => unknown;
export class Router {
  routes: {method: string; path: string; handler: Handler}[] = [];
  get(path: string, handler: Handler) { this.routes.push({method:'GET',path,handler}); }
  post(path: string, handler: Handler) { this.routes.push({method:'POST',path,handler}); }
  delete(path: string, handler: Handler) { this.routes.push({method:'DELETE',path,handler}); }
}
import {Router} from './framework/router.ts';
import {registerAccounts} from './routes/accounts.ts';
import {registerOrders} from './routes/orders.ts';
export function makeRouter() {const router=new Router();registerAccounts(router);registerOrders(router);return router;}
import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
test('five routes registered',()=>assert.equal(makeRouter().routes.length,5));

